// README (ronda 118) · El nombre del producto se guarda en español en el pedido (y así va en la factura); en el mail se
// muestra en el idioma del cliente: «Invitación Boda · Garden Basic» → «Wedding invitation · Garden Basic».
const PRODUCTO = {
  en: { pre: '{t} invitation', boda: 'Wedding', '15': 'Quinceañera', bautismo: 'Baptism', comunion: 'First Communion', cumple: 'Birthday', infantil: "Kids' birthday", graduacion: 'Graduation', babyshower: 'Baby shower', revelacion: 'Gender reveal', navidad: 'Christmas' },
  pt: { pre: 'Convite de {t}', boda: 'Casamento', '15': '15 anos', bautismo: 'Batizado', comunion: 'Primeira Comunhão', cumple: 'Aniversário', infantil: 'Aniversário infantil', graduacion: 'Formatura', babyshower: 'Chá de bebê', revelacion: 'Chá revelação', navidad: 'Natal' },
  fr: { pre: 'Invitation {t}', boda: 'Mariage', '15': '15 ans', bautismo: 'Baptême', comunion: 'Communion', cumple: 'Anniversaire', infantil: 'Anniversaire enfant', graduacion: 'Remise de diplôme', babyshower: 'Baby shower', revelacion: 'Gender reveal', navidad: 'Noël' },
  it: { pre: 'Invito {t}', boda: 'Matrimonio', '15': '15 anni', bautismo: 'Battesimo', comunion: 'Comunione', cumple: 'Compleanno', infantil: 'Compleanno bambini', graduacion: 'Laurea', babyshower: 'Baby shower', revelacion: 'Gender reveal', navidad: 'Natale' },
  de: { pre: 'Einladung {t}', boda: 'Hochzeit', '15': '15. Geburtstag', bautismo: 'Taufe', comunion: 'Kommunion', cumple: 'Geburtstag', infantil: 'Kindergeburtstag', graduacion: 'Abschluss', babyshower: 'Babyparty', revelacion: 'Gender Reveal', navidad: 'Weihnachten' },
  nl: { pre: 'Uitnodiging {t}', boda: 'Bruiloft', '15': '15 jaar', bautismo: 'Doop', comunion: 'Communie', cumple: 'Verjaardag', infantil: 'Kinderfeestje', graduacion: 'Diploma-uitreiking', babyshower: 'Babyshower', revelacion: 'Gender reveal', navidad: 'Kerst' },
};
const TIPOS_ES = { boda: 'Boda', '15': '15 años', bautismo: 'Bautismo', comunion: 'Comunión', cumple: 'Cumpleaños', infantil: 'Cumpleaños infantil', graduacion: 'Egreso / Graduación', babyshower: 'Baby shower', revelacion: 'Revelación de género', navidad: 'Navidad' };
export function productoEn(producto, lengua) {
  const L = PRODUCTO[lengua]; const p = String(producto || '');
  if (!L || !p.startsWith('Invitación ')) return p;
  // El tipo más largo primero («Cumpleaños infantil» antes que «Cumpleaños»)
  const tipo = Object.keys(TIPOS_ES).sort((a, b) => TIPOS_ES[b].length - TIPOS_ES[a].length).find((k) => p.startsWith(`Invitación ${TIPOS_ES[k]}`));
  if (!tipo) return p;
  return L.pre.replace('{t}', L[tipo]) + p.slice(`Invitación ${TIPOS_ES[tipo]}`.length);
}
